def min_replacements_to_lucky(ticket):
    first_half_sum = int(ticket[:3])
    second_half_sum = int(ticket[3:])

    if first_half_sum == second_half_sum:
        return 0

    min_changes = float('inf')

    for i in range(3):
        for j in range(i + 1, 3):
            for k in range(j + 1, 3):
                for l in range(3, 6):
                    for m in range(l + 1, 6):
                        for n in range(m + 1, 6):
                            new_ticket = list(ticket)
                            new_ticket[i] = str(first_half_sum - (int(new_ticket[j]) + int(new_ticket[k])))
                            new_ticket[l] = str(second_half_sum - (int(new_ticket[m]) + int(new_ticket[n])))
                            if int(''.join(new_ticket[:3])) == int(''.join(new_ticket[3:])):
                                changes = sum(d != e for d, e in zip(ticket, ''.join(new_ticket)))
                                min_changes = min(min_changes, changes)

    return min_changes

