def min_replacements_to_lucky_ticket(ticket):
    n = len(ticket)
    dp = [[float('inf')] * 10 for _ in range(n)]

    # Initialize the base case
    dp[0][int(ticket[0])] = 0

    for i in range(1, n):
        d = int(ticket[i])
        for j in range(10):
            dp[i][(j + d) % 10] = min(dp[i][(j + d) % 10], dp[i-1][j] + 1)
            for k in range(10):
                dp[i][(k + d) % 10] = min(dp[i][(k + d) % 10], dp[i-1][k])

    return min(dp[n-1])

